-- ============================================================================
-- E-commerce analytical queries (PostgreSQL-compatible)
-- Run against SYNTHETIC data generated by data/generate_data.py.
-- Demonstrates: joins, CTEs, window functions, NTILE segmentation, RFM.
-- ============================================================================

-- Q1. Monthly revenue trend with month-over-month growth ---------------------
-- Line-item revenue = quantity * unit_price * (1 - discount)
WITH monthly AS (
    SELECT DATE_TRUNC('month', o.order_date)::date AS month,
           SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS revenue
    FROM orders o
    JOIN order_items oi ON oi.order_id = o.order_id
    WHERE o.status <> 'Cancelled'
    GROUP BY 1
)
SELECT month,
       ROUND(revenue, 2) AS revenue,
       ROUND(LAG(revenue) OVER (ORDER BY month), 2) AS prev_month_revenue,
       ROUND(100.0 * (revenue - LAG(revenue) OVER (ORDER BY month))
             / NULLIF(LAG(revenue) OVER (ORDER BY month), 0), 2) AS mom_growth_pct
FROM monthly
ORDER BY month;

-- Q2. Top product categories by revenue and profit ----------------------------
SELECT p.category,
       COUNT(DISTINCT o.order_id) AS orders,
       SUM(oi.quantity) AS units_sold,
       ROUND(SUM(oi.quantity * oi.unit_price * (1 - oi.discount)), 2) AS revenue,
       ROUND(SUM(oi.quantity * (oi.unit_price * (1 - oi.discount) - p.cost)), 2) AS profit
FROM order_items oi
JOIN orders o   ON o.order_id = oi.order_id
JOIN products p ON p.product_id = oi.product_id
WHERE o.status <> 'Cancelled'
GROUP BY p.category
ORDER BY revenue DESC;

-- Q3. Customer lifetime value (LTV) — top 20 ----------------------------------
WITH customer_revenue AS (
    SELECT o.customer_id,
           COUNT(DISTINCT o.order_id) AS orders,
           SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS revenue
    FROM orders o
    JOIN order_items oi ON oi.order_id = o.order_id
    WHERE o.status <> 'Cancelled'
    GROUP BY o.customer_id
)
SELECT c.customer_id, c.name, c.city, c.segment,
       cr.orders,
       ROUND(cr.revenue, 2) AS lifetime_value,
       ROUND(cr.revenue / NULLIF(cr.orders, 0), 2) AS avg_order_value
FROM customer_revenue cr
JOIN customers c ON c.customer_id = cr.customer_id
ORDER BY lifetime_value DESC
LIMIT 20;

-- Q4. RFM segmentation with NTILE --------------------------------------------
-- Recency: days since last order; Frequency: order count; Monetary: revenue.
WITH rfm_base AS (
    SELECT o.customer_id,
           MAX(o.order_date) AS last_order,
           COUNT(DISTINCT o.order_id) AS frequency,
           SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS monetary
    FROM orders o
    JOIN order_items oi ON oi.order_id = o.order_id
    WHERE o.status <> 'Cancelled'
    GROUP BY o.customer_id
),
rfm_scored AS (
    SELECT customer_id,
           NTILE(5) OVER (ORDER BY last_order DESC)      AS r_score,
           NTILE(5) OVER (ORDER BY frequency)            AS f_score,
           NTILE(5) OVER (ORDER BY monetary)             AS m_score
    FROM rfm_base
)
SELECT CASE
           WHEN r_score >= 4 AND f_score >= 4 THEN 'Champions'
           WHEN r_score >= 4 THEN 'Recent buyers'
           WHEN f_score >= 4 THEN 'Frequent buyers'
           WHEN r_score <= 2 AND f_score <= 2 THEN 'At risk'
           ELSE 'Others'
       END AS rfm_segment,
       COUNT(*) AS customers
FROM rfm_scored
GROUP BY 1
ORDER BY customers DESC;

-- Q5. Return rate by product category ------------------------------------------
WITH category_items AS (
    SELECT p.category,
           COUNT(*) AS items_sold,
           COUNT(r.order_id) AS items_returned
    FROM order_items oi
    JOIN orders o   ON o.order_id = oi.order_id
    JOIN products p ON p.product_id = oi.product_id
    LEFT JOIN returns r
           ON r.order_id = oi.order_id AND r.product_id = oi.product_id
    WHERE o.status = 'Delivered'
    GROUP BY p.category
)
SELECT category,
       items_sold,
       items_returned,
       ROUND(100.0 * items_returned / NULLIF(items_sold, 0), 2) AS return_rate_pct
FROM category_items
ORDER BY return_rate_pct DESC;

-- Q6. New vs returning customers per month -------------------------------------
WITH first_orders AS (
    SELECT customer_id, MIN(order_date) AS first_order_date
    FROM orders
    WHERE status <> 'Cancelled'
    GROUP BY customer_id
)
SELECT DATE_TRUNC('month', o.order_date)::date AS month,
       COUNT(DISTINCT CASE WHEN o.order_date = f.first_order_date
                           THEN o.customer_id END) AS new_customers,
       COUNT(DISTINCT CASE WHEN o.order_date > f.first_order_date
                           THEN o.customer_id END) AS returning_customers
FROM orders o
JOIN first_orders f ON f.customer_id = o.customer_id
WHERE o.status <> 'Cancelled'
GROUP BY 1
ORDER BY month;

-- Q7. Payment method mix -------------------------------------------------------
SELECT payment_method,
       COUNT(*) AS orders,
       ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS pct_of_orders,
       ROUND(SUM(oi.quantity * oi.unit_price * (1 - oi.discount)), 2) AS revenue
FROM orders o
JOIN order_items oi ON oi.order_id = o.order_id
WHERE o.status <> 'Cancelled'
GROUP BY payment_method
ORDER BY orders DESC;

-- Q8. Top 10 products by revenue with running total (window function) ----------
WITH product_revenue AS (
    SELECT p.product_id, p.name, p.category,
           SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS revenue
    FROM order_items oi
    JOIN orders o   ON o.order_id = oi.order_id
    JOIN products p ON p.product_id = oi.product_id
    WHERE o.status <> 'Cancelled'
    GROUP BY p.product_id, p.name, p.category
),
ranked AS (
    SELECT *, ROW_NUMBER() OVER (ORDER BY revenue DESC) AS rn
    FROM product_revenue
)
SELECT product_id, name, category,
       ROUND(revenue, 2) AS revenue,
       ROUND(SUM(revenue) OVER (ORDER BY rn)
             / SUM(revenue) OVER (), 4) AS cumulative_revenue_share
FROM ranked
WHERE rn <= 10
ORDER BY rn;
